import{_ as a,o,c as t,a2 as r}from"./chunks/framework.DdtnLau3.js";const g=JSON.parse('{"title":"Work","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/work.md","filePath":"concepts/work.md"}'),n={name:"concepts/work.md"};function i(s,e,c,d,p,l){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="work" tabindex="-1">Work <a class="header-anchor" href="#work" aria-label="Permalink to &quot;Work&quot;">​</a></h1><p>A <strong>Work packages a runnable workspace</strong>. It is the unit you name, start, stop, export, and import in Piwork.</p><p>For example, a Kanban Work can hold the board application, its saved data, tools for operating it, instructions for its Harness, and the history of changes made together. Keeping these resources in one Work gives you an environment you can continue using.</p><h2 id="what-belongs-to-a-work" tabindex="-1">What belongs to a Work? <a class="header-anchor" href="#what-belongs-to-a-work" aria-label="Permalink to &quot;What belongs to a Work?&quot;">​</a></h2><ul><li>Workspace files, source code, and application data stored in managed volumes.</li><li>Service definitions and fixed container images.</li><li>Its Harness configuration, <code>AGENTS.md</code>, Skills, and Pi Packages.</li><li>Conversation history and durable control history.</li><li>Active, desired, and retained configuration needed to restore that workspace.</li></ul><p>The Agent has a private data volume and a shared workspace at <code>/var/data/workspace</code>. Services can share that workspace when their configuration allows it. Store data you want to move in managed storage; temporary container files are outside the portable boundary.</p><h2 id="running-and-changing" tabindex="-1">Running and changing <a class="header-anchor" href="#running-and-changing" aria-label="Permalink to &quot;Running and changing&quot;">​</a></h2><p>Starting a Work runs its Harness and restores enabled Services. Stopping it preserves persistent files, history, and definitions.</p><p>Some configuration edits create a <strong>desired</strong> configuration. They take effect when you explicitly <strong>Apply</strong> them. Keep the saved configuration and the running Harness&#39;s loaded configuration distinct.</p><h2 id="moving-a-work" tabindex="-1">Moving a Work <a class="header-anchor" href="#moving-a-work" aria-label="Permalink to &quot;Moving a Work&quot;">​</a></h2><p><strong>Stop → Export → Share → Import → Start → Continue</strong></p><p>Export creates a <code>.work</code> archive from a stopped Work. Import creates a new independent Work with new platform identities and leaves it stopped. Start it when you are ready to continue.</p><p>The archive carries fixed image content and durable workspace state. It does not contain live process memory or services running outside Piwork. The recipient must configure compatible models and credentials separately.</p><p>Files and history are copied without filtering user content. Check what you saved before sharing a Work: a credential in a source file or conversation travels with it.</p><p>Follow <a href="/piwork/guide/first-work.html">Your First Work</a> for the commands, or read the <a href="/piwork/spec/work.html">Work package specification</a>.</p>',15)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
